-- Supabase/PostgreSQL: apply once to an empty monitor database.
-- Access is through the PHP backend; no public Data API policies.
SET search_path = public;
CREATE TABLE IF NOT EXISTS news(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(500) NOT NULL,description TEXT,content_excerpt TEXT,url TEXT NOT NULL,canonical_url VARCHAR(1000) NOT NULL,source_name VARCHAR(255),source_domain VARCHAR(255),published_at TIMESTAMP,discovered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,image_url TEXT,status VARCHAR(30) DEFAULT 'active',is_new SMALLINT DEFAULT 1,is_read SMALLINT DEFAULT 0,category VARCHAR(100),search_term VARCHAR(255),content_hash CHAR(64) NOT NULL,relevance_score SMALLINT DEFAULT 0,relevance_status VARCHAR(30) DEFAULT 'manual_review',relevance_reason TEXT,analysis_source VARCHAR(30) DEFAULT 'metadata',matched_entities JSONB,manual_reviewed SMALLINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(content_hash));
CREATE TABLE IF NOT EXISTS sources(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL,type VARCHAR(30) DEFAULT 'rss',url VARCHAR(1000) NOT NULL,active SMALLINT DEFAULT 1,last_checked_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS search_terms(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,term VARCHAR(255) NOT NULL UNIQUE,weight INT DEFAULT 10,active SMALLINT DEFAULT 1,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS case_entities(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL,normalized_name VARCHAR(255) NOT NULL,type VARCHAR(80) NOT NULL,relevance_weight INT DEFAULT 20,active SMALLINT DEFAULT 1,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS monitor_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,source_id INTEGER NULL,search_term VARCHAR(255),status VARCHAR(30) NOT NULL,total_results INT DEFAULT 0,new_results INT DEFAULT 0,related_results INT DEFAULT 0,review_results INT DEFAULT 0,discarded_results INT DEFAULT 0,message TEXT,executed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_logs_source FOREIGN KEY(source_id) REFERENCES sources(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,setting_key VARCHAR(100) NOT NULL UNIQUE,setting_value TEXT);
CREATE TABLE IF NOT EXISTS manual_reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,news_id BIGINT NOT NULL,previous_status VARCHAR(30),new_status VARCHAR(30) NOT NULL,notes TEXT,reviewed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_review_news FOREIGN KEY(news_id) REFERENCES news(id) ON DELETE CASCADE);
