CREATE INDEX idx_news_canonical ON public.news(canonical_url);
CREATE INDEX idx_news_relevance ON public.news(relevance_status,relevance_score);
CREATE INDEX idx_news_discovered ON public.news(discovered_at);
CREATE INDEX idx_entities_normalized ON public.case_entities(normalized_name);
CREATE INDEX idx_logs_source ON public.monitor_logs(source_id);
CREATE INDEX idx_logs_executed ON public.monitor_logs(executed_at DESC);
CREATE INDEX idx_reviews_news ON public.manual_reviews(news_id);
ALTER TABLE public.news ADD CHECK (relevance_score BETWEEN 0 AND 100), ADD CHECK (relevance_status IN ('related','possibly_related','unrelated','manual_review')), ADD CHECK (analysis_source IN ('full_content','metadata'));
CREATE FUNCTION public.monitor_set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$ BEGIN NEW.updated_at = CURRENT_TIMESTAMP; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.monitor_set_updated_at() FROM PUBLIC;
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.news FOR EACH ROW EXECUTE FUNCTION public.monitor_set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.sources FOR EACH ROW EXECUTE FUNCTION public.monitor_set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.search_terms FOR EACH ROW EXECUTE FUNCTION public.monitor_set_updated_at();
CREATE TRIGGER set_updated_at BEFORE UPDATE ON public.case_entities FOR EACH ROW EXECUTE FUNCTION public.monitor_set_updated_at();
ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.news FROM anon, authenticated;
ALTER TABLE public.sources ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.sources FROM anon, authenticated;
ALTER TABLE public.search_terms ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.search_terms FROM anon, authenticated;
ALTER TABLE public.case_entities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.case_entities FROM anon, authenticated;
ALTER TABLE public.monitor_logs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.monitor_logs FROM anon, authenticated;
ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.settings FROM anon, authenticated;
ALTER TABLE public.manual_reviews ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.manual_reviews FROM anon, authenticated;
